parameters.jsCode:
// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by sys.gateway@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before sys.gateway started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "sys.gateway",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "sys.gateway", capability_version: "1.0.0",
  layer: "system", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// Tenancy is established HERE and nowhere else. Everything downstream trusts envelope.tenant_id
// absolutely, so this is the one place that must get it right.
const trigger = $execution?.customData?.get?.('trigger') || $json.__trigger || 'unknown';
const TENANT_MAP = JSON.parse($env.MOS_TENANT_MAP || '{}');

let source_channel = 'api', external_id = null, text = '', raw = $json;

if ($json.message || $json.callback_query) {
  source_channel = 'telegram';
  external_id = String($json.message?.chat?.id ?? $json.callback_query?.message?.chat?.id ?? '');
  text = $json.message?.text || $json.message?.caption || '';
} else if ($json.headers) {
  source_channel = $json.body?.source || 'webhook';
  external_id = $json.headers['x-mos-tenant'] || $json.body?.tenant_id || null;
  text = $json.body?.text || $json.body?.prompt || '';
  raw = $json.body;
} else if ($json.__schedule) {
  source_channel = 'schedule';
  external_id = $json.tenant_id;
  text = $json.prompt || '';
}

const tenant = TENANT_MAP[`${source_channel}:${external_id}`] || TENANT_MAP[external_id] || null;
if (!tenant) {
  throw new Error(`POLICY_BLOCKED: unrecognised source ${source_channel}:${external_id} — refusing to process work for an unmapped tenant`);
}

return [{ json: { source_channel, external_id, text, raw, tenant } }];

// One envelope, minted once, carried everywhere. Its policy block is the CEILING for this run:
// downstream units may narrow it, never widen it.
const crypto = require('crypto');
const s = $json;
const t = s.tenant;
const trace_id = 'trc_' + crypto.randomUUID().replace(/-/g, '').slice(0, 20);
const idem = crypto.createHash('sha256').update([t.tenant_id, s.source_channel, s.external_id, s.text, new Date().toISOString().slice(0, 13)].join('|')).digest('hex');

return [{ json: {
  envelope_version: '1.0.0',
  trace_id,
  span_id: 'spn_' + crypto.randomUUID().slice(0, 8),
  parent_span_id: null,
  tenant_id: t.tenant_id,
  brand_id: t.default_brand_id || null,
  vertical: t.vertical || 'generic',
  locale: t.locale || 'en-US',
  region: t.region || 'us',
  intent: 'intake.received',
  stage: 'intake',
  idempotency_key: idem,
  attempt: 1,
  max_attempts: 3,
  deadline_at: new Date(Date.now() + (t.deadline_minutes ?? 30) * 60000).toISOString(),
  policy: {
    autonomy_level: t.autonomy_level || 'publish_with_approval',
    compliance_profile: t.compliance_profile || 'standard',
    approval_mode: t.approval_mode || 'channel_conditional',
    data_residency: t.data_residency || 'any',
    pii_redaction: t.pii_redaction !== false,
    allow_external_research: t.allow_external_research !== false,
    model_tier_cap: t.model_tier_cap || 'frontier'
  },
  budget: {
    currency: t.currency || 'USD',
    cap_minor_units: t.run_budget_minor_units ?? 2000,
    spent_minor_units: 0,
    soft_limit_pct: 0.8,
    on_soft_limit: 'downgrade_tier'
  },
  routing: {},
  payload: { source_channel: s.source_channel, raw: s.raw, text: s.text, reply_to: s.external_id },
  provenance: [],
  error: null
} }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "sys.gateway",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 0,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "sys.gateway", capability_version: "1.0.0",
    layer: "system", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

